boolean unify(Node m, Node n) { 
8 = find(m); t = find(n); 
if ( 8 = t ) return true; 
else if ( nodes 8 and t represent the same basic type ) return true; 
} 
else if (8 is an op-node with children 81 and 82 and 
t is an op-node with children h and t2) { 
union(8, t); 
